parameters.jsCode:
const postResp = $('JARVIS — Générer Post LinkedIn').first().json;
const hashResp = $('JARVIS — Hashtags Trending').first().json;

const postContent = postResp?.response || postResp?.content || postResp?.message || 'Post généré par JARVIS IA';
const now = new Date();
const timeStr = now.toLocaleString('fr-FR');

const linkedinPost = `${postContent}\n\n---\n📅 Publié via JARVIS AI Cluster v12.6\n🤖 Généré par orchestration multi-GPU locale`;

const summary = `📱 *JARVIS LinkedIn Growth — ${timeStr}*\n\n📝 *Post généré:*\n${postContent.substring(0, 200)}...\n\n✅ Prêt pour publication manuelle ou API LinkedIn`;

return [{ json: { linkedinPost, summary, generatedAt: timeStr, charCount: linkedinPost.length } }];

